function normalize(value = '') { return value.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim() }
function formatDate(value) { if (!value) return ''; const date = new Date(`${value}T12:00:00`); return Number.isNaN(date.getTime()) ? esc(value) : new Intl.DateTimeFormat('es-BO', { day: 'numeric', month: 'short', year: 'numeric' }).format(date) }
function formatTimestamp(value) { if (!value) return ''; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat('es-BO', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date) }
